from lib import *
S = SS('w74')
steps = [
    step("一个最小的 HTTP/1.1 请求有 56 字节:\"GET / HTTP/1.1\\r\\nHost: example.com\\r\\nConnection: close\\r\\n\\r\\n\"。结构是:请求行(方法、空格、目标、空格、版本)+ CRLF;若干“名字: 值”头部,每行以 CRLF 结束;最后一个空行(再一个 CRLF)标志头部结束。服务器的响应一共 928 字节:状态行 \"HTTP/1.1 200 OK\"(版本、状态码、原因短语),12 个头部共 335 字节,CRLFCRLF 4 字节,消息体 589 字节。这个响应没有 Content-Length,而是 Transfer-Encoding: chunked:消息体一开头是 \"241\\r\\n\",241 是十六进制的块长度(= 577 字节),后面才是 HTML。头部里还能看到 Server: cloudflare、Age: 6 之类的缓存信息和 alt-svc: h3=\":443\"(提示可以改用 HTTP/3)。因为请求带了 Connection: close,服务器发完就关闭了连接。", t=tl(S(1)), mark=lidx(S(1), '发出的请求', '收到 928 字节'), done=lidx(S(1), '状态行:HTTP/1.1 200 OK', '头部共 12 个', '消息体开头'), b=bars([['状态行 + 头部', 335, '335 字节'], ['空行 CRLFCRLF', 4, '4 字节'], ['消息体(chunked)', 589, '589 字节']], 589, mark=[], done=[0, 1, 2]), kv=KV([['请求', '56 字节:请求行 + Host + Connection + 空行'], ['响应', '928 字节 = 335 + 4 + 589'], ['消息体划界', 'Transfer-Encoding: chunked(块长度 0x241)']], ['消息体划界'])),
    step("格式上的宽容度,各发一次看状态码。头部名字全大写 / 乱大小写 → 200;冒号后不加空格、值后多余空格 → 200(头部名字不区分大小写,值两侧的空白被忽略);行尾只用 LF 而不是 CRLF → 200(服务器比规范宽容);请求目标写成绝对 URI → 200;同一个头出现两次(Host 写了 example.com 和 example.org)→ 200(规范要求拒绝,这个服务器没有拒绝)。被拒绝的是:缺少 Host 头 → 400 Bad Request(HTTP/1.1 要求必须有);未知方法 FOO → 405 Method Not Allowed;版本号 HTTP/9.9 → 505 HTTP Version Not Supported。", t=tl(S(2)), mark=lidx(S(2), '缺少 Host 头', '未知方法 FOO', '版本号写成'), done=lidx(S(2), '正常', '头部名字全大写', '冒号后无空格', '行尾只用 LF', '请求目标是绝对 URI', '同一个头出现两次'), kv=KV([['宽容(200)', '大小写乱、无空格、LF 行尾、绝对 URI、重复 Host'], ['400', '缺少 Host'], ['405', '未知方法'], ['505', '版本 HTTP/9.9']], ['400'])),
    step("HTTP/1.0 与 HTTP/1.1 的默认连接行为:不写 Connection 头。请求 HTTP/1.0:服务器响应状态行仍是 HTTP/1.1 200 OK,响应头里 Connection: close,并在 498 ms 时关闭了连接——1.0 的默认是用完即关。请求 HTTP/1.1:响应头里 Connection: keep-alive,读了 5 秒服务器也没有关闭连接——1.1 的默认是持久连接,等着下一个请求。注意即使请求是 1.0,响应也写着 HTTP/1.1:服务器按自己支持的最高版本回答。", t=tl(S(3)), mark=lidx(S(3), '请求 HTTP/1.0', '请求 HTTP/1.1'), done=lidx(S(3), '请求 HTTP/1.0'), kv=KV([['HTTP/1.0', 'Connection: close,498 ms 关闭'], ['HTTP/1.1', 'Connection: keep-alive,5 秒不关'], ['响应版本', '都写 HTTP/1.1']], ['HTTP/1.1'])),
    step("头部大小的限制:把一个 X-Pad 头部的值越拉越长。1000、16000、64000、100000、130000 字节都返回 200;200000 和 400000 字节返回 400 Bad Request。所以这个服务器单个头部的上限在 130000 ~ 200000 字节之间(我没有进一步二分)。对客户端的含义:超大的 Cookie 或自定义头在服务器端会直接被拒;而多数网关和代理的限制要小得多(常见是 8~16 KB),这里测到的只是这一个服务器。", t=tl(S(4)), mark=lidx(S(4), 'X-Pad 长度 200000', 'X-Pad 长度 400000'), done=lidx(S(4), 'X-Pad 长度  1000', 'X-Pad 长度 130000'), b=bars([['通过的最大头部值', 130000, '130000'], ['被拒绝的最小头部值', 200000, '200000']], 200000, mark=[1], done=[0]), kv=KV([['130000 字节', '200 OK'], ['200000 字节', '400 Bad Request'], ['上限', '130000~200000 之间']], ['上限'])),
]
A = mkartw('w74', 74, '网络协议,HTTP,HTTP/1.1,报文格式,请求行,头部,chunked,真实验证,动画演示',
    '手工拆解 HTTP/1.1 报文:56 字节的请求、928 字节的响应(335 字节头部 + 4 + 589 字节分块消息体);头部大小写与 LF 行尾都被接受,缺 Host 得 400,未知方法 405,版本 HTTP/9.9 得 505;1.0 默认关连接、1.1 默认保持;单个头部上限在 130000~200000 字节之间。',
    'HTTP/1.1 是文本协议:请求行、头部、一个空行、消息体。看起来简单,但细节里藏着很多规则:怎么划分头部结束、名字大小写、必须有的 Host、什么时候关连接。这篇手工拼请求发给 example.com,逐项看服务器的真实反应,包括它比规范更宽容的地方。',
    [('56 / 928 字节', '最小 GET 请求与 example.com 的响应大小'), ('0x241', '响应消息体第一行的十六进制块长度(= 577 字节),因为用的是 chunked'), ('130000~200000', '单个头部值通过与被拒绝(400)的字节数区间')],
    [('报文结构', '<p>请求行或状态行、若干头部、空行 CRLFCRLF、消息体。响应用 chunked 划界,首行是十六进制块长度。</p>'),
     ('宽容与拒绝', '<p>大小写乱、LF 行尾、绝对 URI 都被接受;缺 Host → 400,未知方法 → 405,HTTP/9.9 → 505。</p>'),
     ('持久连接默认值', '<p>1.0 默认关闭,1.1 默认保持;响应头的 Connection 会明确说明。</p>'),
     ('头部大小', '<p>这个服务器单个头部值的上限在 130000~200000 字节之间,超过就是 400。</p>')],
    steps,
    [ENV_W + '。全部是对 example.com:80(Cloudflare)的明文 HTTP/1.1 请求;每种畸形请求只发一次;其它服务器的宽容度不同,这里的结论只对这一个服务器成立;响应里的 Age、CF-RAY 等每次不同',
     '没有验证:请求走私(同时带 Content-Length 和 Transfer-Encoding);头部折行(obs-fold);请求体与 Expect: 100-continue;HTTP/1.1 流水线(下一篇);其它服务器(nginx、Apache、Python http.server)对同样畸形请求的反应;头部上限的精确值'],
    'HTTP/1.1 报文')
